<?php use VO\Support\Template; ob_start(); ?>
<h1>Productos</h1><?php foreach ($errors as $e): ?><p class="error"><?= Template::e($e) ?></p><?php endforeach; ?>
<form method="post" action="/admin/productos" class="card"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><label>Nombre <input name="name"></label><label>Slug <input name="slug"></label><label>Tipo <select name="type"><option value="product">Producto</option><option value="service">Servicio</option></select></label><label>Precio base en centavos <input name="base_price_cents"></label><label><input type="checkbox" name="requires_variant" value="1"> Requiere variante</label><label><input type="checkbox" name="allows_pickup" value="1" checked> Retiro</label><label><input type="checkbox" name="allows_delivery" value="1"> Envío</label><label><input type="checkbox" name="is_active" value="1" checked> Activo</label><h2>Variantes</h2><input name="variant_name[]" placeholder="Nombre"><input name="variant_price_cents[]" placeholder="Precio"><h2>Modificadores</h2><?php foreach ($groups as $g): ?><label><input type="checkbox" name="modifier_group_id[]" value="<?= (int)$g['id'] ?>"> <?= Template::e($g['name']) ?></label><?php endforeach; ?><h2>Imágenes</h2><fieldset><label>Archivo <input name="image_filename[]" placeholder="foto.jpg"></label><label>Orden <input name="image_sort[]" value="0"></label><label>Texto alternativo <input name="image_alt[]" placeholder="Descripción de la imagen"></label></fieldset><button class="btn">Guardar producto</button></form>
<section class="card"><h2>Listado</h2><?php foreach ($items as $i): ?><p><a href="/admin/producto/<?= (int)$i['id'] ?>"><?= Template::e($i['name']) ?></a> <span class="muted"><?= Template::e($i['slug']) ?></span></p><?php endforeach; ?></section>
<?php $content = ob_get_clean(); $title = 'Productos'; require __DIR__ . '/layout.php'; ?>
